using EnglishVoiceTutor.Desktop.Models;
using EnglishVoiceTutor.Shared.NativeLanguages;

namespace EnglishVoiceTutor.Desktop.Localization;

public static class AppLocalization
{
    private static readonly Lazy<IReadOnlyDictionary<string, AppLocalizedText>> TextByLanguageId = new(BuildTextByLanguageId);

    public static AppLocalizedText GetText(string? languageId)
    {
        var normalizedLanguageId = NormalizeLanguageId(languageId);
        return TextByLanguageId.Value.TryGetValue(normalizedLanguageId, out var text) ? text : TextByLanguageId.Value[InterfaceLanguageOptions.EnglishId];
    }

    public static SettingsLocalizedText GetSettingsText(string? languageId) => GetText(languageId).Settings;

    public static string GetLearnerUiText(string? languageId, string englishText)
    {
        var normalizedLanguageId = NormalizeLanguageId(languageId);
        return LearnerUiTextByLanguageId.TryGetValue(normalizedLanguageId, out var texts) && texts.TryGetValue(englishText, out var localizedText)
            ? localizedText
            : englishText;
    }

    public static LocalizedDisplayText GetTopicDisplayText(string? languageId, string title, string description)
    {
        return GetDisplayText(GetText(languageId).TopicDisplayTextByTitle, title, description);
    }

    public static LocalizedDisplayText GetSubtopicDisplayText(string? languageId, string title, string description)
    {
        return GetDisplayText(GetText(languageId).SubtopicDisplayTextByTitle, title, description);
    }

    public static string NormalizeLanguageId(string? languageId)
    {
        return InterfaceLanguageOptions.GetById(languageId).Id;
    }

    private static IReadOnlyDictionary<string, AppLocalizedText> BuildTextByLanguageId()
    {
        var result = new Dictionary<string, AppLocalizedText>(StringComparer.OrdinalIgnoreCase);
        foreach (var language in InterfaceLanguageOptions.All)
        {
            var terms = TermsByLanguageId.TryGetValue(language.Id, out var localizedTerms) ? localizedTerms : EnglishTerms;
            result[language.Id] = CreateText(language.Id, terms);
        }
        return result;
    }

    private static AppLocalizedText CreateText(string languageId, UiTerms t)
    {
        var p = PhrasesByLanguageId.TryGetValue(languageId, out var localizedPhrases) ? localizedPhrases : EnglishPhrases;
        string l(string englishText) => GetLearnerUiText(languageId, englishText);
        var settings = new SettingsLocalizedText(
            t.Settings,
            p.SettingsSubtitle,
            t.InterfaceLanguage,
            t.NativeLanguage,
            p.NativeLanguageSubtitle,
            l("Connection"),
            l("Server endpoint"),
            l("Used by the app to reach the local or remote backend."),
            l("Your profile"),
            l("This helps your tutor personalize lessons."),
            l("Your name"),
            l("Learning goal"),
            t.TutorAvatar,
            p.TutorAvatarSubtitle,
            l("Avatar profile"),
            l("Age"),
            l("Location"),
            l("Role"),
            l("Interests"),
            l("Personality"),
            l("Speaking style"),
            t.Progress,
            l("Based on completed lessons on this device."),
            l("Total completed lessons"),
            l("Lessons completed today"),
            l("Current streak"),
            l("Last completed lesson"),
            l("No completed lessons yet."),
            t.Save,
            t.Back,
            p.SettingsSavedMessage,
            t.Audio,
            t.Microphone,
            l("System default"),
            t.TestMicrophone,
            t.RefreshMicrophones,
            l("Microphone test completed."),
            l("No microphone found."),
            l("Selected microphone is unavailable. Using system default."),
            t.StudyLanguage,
            p.StudyLanguageSubtitle,
            t.Account,
            l("Sign in or create an account to start lessons. A 7-day trial starts automatically after registration."),
            t.Email,
            t.Password,
            t.DisplayName,
            t.Register,
            t.Login,
            t.Logout,
            t.CurrentAccount,
            t.SettingsSource,
            t.SubscriptionStatus,
            t.Plan,
            t.Premium,
            t.Trial,
            l("Free lesson today"),
            l("Enforcement"),
            l("Source"),
            l("Checked"),
            t.Close,
            t.RefreshStatus,
            t.Upgrade,
            t.Diagnostics,
            t.Learning,
            t.Progress,
            l("Forgot password?"),
            l("Request reset instructions by email, then paste the reset code and choose a new password."),
            l("Send reset instructions"),
            l("Reset code"),
            l("New password"),
            l("Confirm new password"),
            l("Reset password"),
            l("Change password"),
            l("Update the password for the signed-in account."),
            l("Current password"),
            l("Change password"));

        return new AppLocalizedText(
            languageId, settings,
            l("Foreign language speaking practice"),
            l("Practice real-life lessons by text or voice with AI guidance."),
            t.StartLesson,
            t.Settings,
            l("Sign in to account"),
            l("Signed in as {0}"),
            l("Signed in"),
            t.ChooseLevel, l("We will use this level later to adapt lessons and corrections."), $"{t.Level}:", l("Please select a level before continuing."), t.Continue, t.Back,
            t.Home, p.HomeSubtitle, $"{t.Level}:", p.DailyLimitText, l("Lesson history"), t.Settings,
            SubtopicsLocalization.GetTitleTemplate(languageId), SubtopicsLocalization.GetSubtitle(languageId), $"{t.Topic}:", $"{t.Situation}:", l("Please choose a situation before starting the lesson."), t.StartLesson,
            t.LessonChat, $"{t.Topic}:", $"{t.Situation}:", $"{t.Level}:", t.Send, t.StartRecording, t.StopRecording, t.Hint, p.AutoSendVoiceLabel, p.AutoSendVoiceToolTip, p.AutoPlayBotVoiceLabel, p.AutoPlayBotVoiceToolTip, t.FinishLesson, l("Finish lesson?"), l("This lesson is still active. Do you want to finish it now?"), t.FinishLesson, l("Continue lesson"), t.ConversationMode, l("Back to chat"), l("Back to chat"), t.ShowTranslation, t.HideTranslation, t.Translation, t.PlayVoice, l("View feedback"), t.Hint, l("Click to close"), l("Feedback"), l("Corrected version"), l("Grammar tip"), l("Vocabulary tip"), l("Culture tip"), l("More natural version"), l("Translate feedback"), l("Hide feedback translation"), l("Feedback translation"), l("Bot status:"), l("Ready"), l("Thinking"),
            l("Recording... Click Stop recording when you finish."), l("Could not start voice recording. Please check your microphone."), l("Could not stop voice recording. Please try again."), l("Transcribing your voice..."), l("Voice transcription is ready. Review the text and press Send."), l("Could not transcribe the recording. Please try again or type your answer."), l("No speech was recognized. Please try again."), l("Please type your answer before sending."), l("Playing AI-generated bot voice..."), l("Could not play bot voice. Please try again."), l("Backend is unavailable. Please check your connection and try again."), l("Backend health check failed. Please check your connection."), l("Translating..."), l("Could not translate this text. Please try again."), l("Hint: Try answering with a short complete sentence."),
            t.Summary, t.WhatWentWell, t.WhatToImprove, t.UsefulPhrases, t.BackToLessons, t.Back, l("You completed a short practice dialogue and received AI feedback on your response."), l("Keep practicing full sentences and apply the feedback tips to improve grammar and vocabulary."), [l("Could you help me, please?"), l("I would like to..."), l("Could you repeat that, please?"), l("That sounds good to me.")],
            l("Lesson history"), l("Recent completed lessons on this device."), l("No completed lessons yet. Finish a lesson to see it here."), BuildTopicDisplayText(languageId), BuildSubtopicDisplayText(languageId));
    }

    private static IReadOnlyDictionary<string, LocalizedDisplayText> BuildTopicDisplayText(string languageId)
    {
        string l(string englishText) => GetLearnerUiText(languageId, englishText);
        return Map(
            ("Daily Life", l("Daily Life"), l("Small talk, introductions, and daily situations.")),
            ("Travel", l("Travel"), l("Airports, hotels, directions, and transport.")),
            ("Work & Business", l("Work & Business"), l("Meetings, emails, calls, and workplace conversations.")),
            ("Job Interview", l("Job Interview"), l("Practice common interview questions and answers.")),
            ("Restaurant & Cafe", l("Restaurant & Cafe"), l("Ordering food, booking tables, and polite requests.")),
            ("Free Conversation", l("Free Conversation"), l("Open English conversation with safe, respectful boundaries.")));
    }

    private static IReadOnlyDictionary<string, LocalizedDisplayText> BuildSubtopicDisplayText(string languageId)
    {
        return SubtopicsLocalization.BuildSubtopicDisplayText(languageId);
    }

    private static LocalizedDisplayText GetDisplayText(IReadOnlyDictionary<string, LocalizedDisplayText> displayTextByTitle, string title, string description)
    {
        if (!string.IsNullOrWhiteSpace(title) && displayTextByTitle.TryGetValue(title, out var displayText))
        {
            return displayText;
        }

        return new LocalizedDisplayText(title, description);
    }

    private static IReadOnlyDictionary<string, LocalizedDisplayText> Map(params (string Key, string Title, string Description)[] values)
    {
        return values.ToDictionary(value => value.Key, value => new LocalizedDisplayText(value.Title, value.Description), StringComparer.OrdinalIgnoreCase);
    }

