        foreach (var languageId in InterfaceLanguageOptions.ReleaseReadyInterfaceLanguageIds)
        {
            if (!billing.TryGetValue(languageId, out var additions))
            {
                continue;
            }

            var merged = texts.TryGetValue(languageId, out var existing)
                ? new Dictionary<string, string>(existing, StringComparer.OrdinalIgnoreCase)
                : new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            foreach (var item in additions)
            {
                merged[item.Key] = item.Value;
            }

            texts[languageId] = merged;
        }
